import{_ as t,o as a,c as r,a0 as n}from"./chunks/framework.BQGW-Zpy.js";const u=JSON.parse('{"title":"Business Model","description":"","frontmatter":{},"headers":[],"relativePath":"business/business-model.md","filePath":"business/business-model.md"}'),s={name:"business/business-model.md"};function o(i,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="business-model" tabindex="-1">Business Model <a class="header-anchor" href="#business-model" aria-label="Permalink to &quot;Business Model&quot;">​</a></h1><h3 id="_9-1-customer" tabindex="-1">9.1 Customer <a class="header-anchor" href="#_9-1-customer" aria-label="Permalink to &quot;9.1 Customer&quot;">​</a></h3><p><strong>Two segments, one payer:</strong></p><ul><li><strong>Freelancers and individuals</strong> in corridors the incumbents underserve, the sender pays a transparent fee</li><li><strong>SMEs</strong> paying contractors abroad, the business pays</li></ul><p><strong>Neither needs crypto knowledge.</strong> That is the entire product.</p><h3 id="_9-2-why-they-would-pay" tabindex="-1">9.2 Why they would pay <a class="header-anchor" href="#_9-2-why-they-would-pay" aria-label="Permalink to &quot;9.2 Why they would pay&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Value</th><th>Basis</th></tr></thead><tbody><tr><td>Corridors that exist</td><td>Where an incumbent has no partner and we do</td></tr><tr><td>Transparent, single fee</td><td>Against a hidden FX spread</td></tr><tr><td>Speed</td><td>Settlement in seconds rather than days</td></tr><tr><td>Provable compliance</td><td>For the SME segment: an audit trail they can hand a regulator</td></tr></tbody></table><h3 id="_9-3-revenue" tabindex="-1">9.3 Revenue <a class="header-anchor" href="#_9-3-revenue" aria-label="Permalink to &quot;9.3 Revenue&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Stream</th><th>Basis</th></tr></thead><tbody><tr><td>FX spread</td><td>The standard mechanism; ours stated explicitly, not hidden</td></tr><tr><td>Flat transfer fee</td><td>Per transaction</td></tr><tr><td>B2B compliance-evidence API</td><td>The verifiable trail, sold to institutions that want it</td></tr><tr><td><strong>Not revenue</strong></td><td>No token. No float income, we hold no float.</td></tr></tbody></table><p><strong>Note on unit economics.</strong> The Hedera fee is negligible (fixed, fractions of a cent). It is <strong>not</strong> where the cost lives. The cost lives in the licensed parties&#39; take: the on-ramp&#39;s card/SEPA fee, the payout partner&#39;s local margin, and the FX spread. <strong>We are a thin margin on top of their margins.</strong> Any claim that blockchain makes this dramatically cheaper is a claim about <em>their</em> costs, not ours, and we do not make it.</p><h3 id="_9-4-capital-lock-up-the-claim-we-retract" tabindex="-1">9.4 Capital lock-up, the claim we retract <a class="header-anchor" href="#_9-4-capital-lock-up-the-claim-we-retract" aria-label="Permalink to &quot;9.4 Capital lock-up, the claim we retract&quot;">​</a></h3><p>A pitch in this space usually says <em>&quot;unlike Wise, we don&#39;t pre-fund 50 countries.&quot;</em></p><p><strong>That is false, and an examiner will see it immediately.</strong> Our payout partner in the destination country must hold local currency to pay out. The float has not disappeared, it has moved onto the partner&#39;s balance sheet, and it returns to us as their fee.</p><p><strong>The defensible version, which is genuinely true:</strong> stablecoin settlement removes the <em>correspondent-banking</em> dependency. Instead of nostro accounts in every country, we need <strong>one liquidity partner per corridor</strong>. That improves capital efficiency and makes some corridors viable that correspondent banking cannot justify. It is a narrower claim. It is also a real one.</p><h3 id="_9-5-network-effects-and-why-we-are-not-blocked-by-them" tabindex="-1">9.5 Network effects, and why we are not blocked by them <a class="header-anchor" href="#_9-5-network-effects-and-why-we-are-not-blocked-by-them" aria-label="Permalink to &quot;9.5 Network effects, and why we are not blocked by them&quot;">​</a></h3><p><em>The question every marketplace gets, and the one that killed the previous cycle&#39;s payment startups.</em></p><p><strong>We are not a two-sided market.</strong> The sender pays; the recipient receives a normal bank credit and never registers, never installs anything, never learns what we are. <strong>The recipient side has no adoption cost at all</strong>, because from their perspective money simply arrived in their account.</p><p>That removes the classic cold-start trap. We do not need a network of users before the first transfer is useful. <strong>One sender, one corridor, one licensed partner, and the product works.</strong></p><p>What we <em>do</em> depend on is <strong>corridor supply</strong>, and that is a commercial problem, not a network-effect problem: it is solved one partner agreement at a time, not by waiting for critical mass.</p><p><strong>Where genuine network effects do appear:</strong></p><ul><li><strong>Liquidity depth per corridor</strong> improves pricing as volume grows, a real but gradual effect</li><li><strong>The compliance-evidence layer</strong> compounds: the more licensed parties anchor to the same topic, the more valuable a verifiable cross-party trail becomes</li></ul><p>Neither is required to start. Both improve the product later. That is the distinction between a network effect that <em>enables</em> and one that <em>gates</em>.</p><h3 id="_9-6-scalability" tabindex="-1">9.6 Scalability <a class="header-anchor" href="#_9-6-scalability" aria-label="Permalink to &quot;9.6 Scalability&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dimension</th><th>Constraint</th><th>Assessment</th></tr></thead><tbody><tr><td><strong>Technical throughput</strong></td><td>Hedera throttles at ~10,000 TPS</td><td>Not the binding constraint by several orders of magnitude. A retail remittance product will never approach it.</td></tr><tr><td><strong>Cost per transaction</strong></td><td>Fixed, USD-denominated, fractions of a cent</td><td>Scales linearly and predictably. <strong>This is why fixed fees matter more than raw TPS</strong>: a payment business must underwrite its unit cost.</td></tr><tr><td><strong>Corridor expansion</strong></td><td>One licensed partner per corridor</td><td><strong>The real constraint.</strong> Linear in partner agreements, not in engineering.</td></tr><tr><td><strong>Compliance load</strong></td><td>Grows with volume and jurisdictions</td><td>Borne by the licensed parties, not us, a structural advantage of the orchestrator model</td></tr><tr><td><strong>Our own scaling</strong></td><td>Stateless orchestration + append-only anchoring</td><td>Horizontally scalable; we hold no balances to reconcile</td></tr></tbody></table><p><strong>Note:</strong> we are not technically constrained. We are <strong>commercially constrained</strong>, and we say so. Scaling this business means signing partners, not adding servers. That is a slower curve than a pure software product, and it is the same curve every licensed competitor faces.</p><h3 id="_9-7-business-sustainability" tabindex="-1">9.7 Business sustainability <a class="header-anchor" href="#_9-7-business-sustainability" aria-label="Permalink to &quot;9.7 Business sustainability&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Answer</th></tr></thead><tbody><tr><td>Where does revenue come from?</td><td>FX spread + flat fee per transfer + the compliance-evidence API</td></tr><tr><td>Is the margin defensible?</td><td>Thin on the payment leg, the licensed parties take most of it. <strong>The defensible margin is the evidence layer</strong>, which costs us fractions of a cent and no one else offers.</td></tr><tr><td>What are the fixed costs?</td><td>Engineering and partner management. <strong>No float, no capital lock-up, no licence capital</strong>, because we hold nothing.</td></tr><tr><td>What would kill it?</td><td>A licensed CASP (Due, BVNK) adding an anchoring layer. We are copyable, and <a href="./../analysis/innovation-ethics.html">this section</a> says so.</td></tr><tr><td>Why would it survive anyway?</td><td>Because they are optimising for corridors with volume. The corridors we target are the ones they have not judged worth the partner work.</td></tr></tbody></table><hr>',28)])])}const m=t(s,[["render",o]]);export{u as __pageData,m as default};
